/*
20240118整理By_zhbyjm7783
部分代码，发现地址，正文解密By_尐哖
同加密app：
必看：https://www.ibreader.com
目录加载失败时多刷新几次
有些有锁章节也可直接阅读
备用：
①网页版https://www.yc.ifeng.com：
搜索：https://www.yc.ifeng.com/book/search/,{
	"method":"post",
	"body":"query={{key}}"
	}
详情页规则：
a.0@href##.*book\/(\d+).*##http://iyc.ifeng.com/api/books/$1##
目录页规则：
http://iyc.ifeng.com/fhxw/bookshelf/directory,{
  "body": "bookId={{$.bookId}}&chapterNum=0&isNext=1&getNum=10000",
  "method": "POST"
}
章节URL规则：
http://iyc.ifeng.com/api/books/@get:{bid}/chapters/{{$.chapterNum}}/content
正文规则：
$.data.txt
②免费趣小说app：
搜索接口By_遇知：
http://androidapi4.yc.ifeng.com/api/freeClient/book/search,{
  "body": "fr10=6.33.0.06&fr11=1080&fr12=2238&fr13=15164564&fr14=381&fr15=15&page={{page}}&pageCount=50&query={{key}}",
  "method": "POST"
}
书籍列表:
$.data.bookList[*]
书名:
$.name
作者:
$.author
分类:
$.category
最新章节:
$.maxPartName
简介:
$.description
封面:
$.picUrl
详情页规则:
$.scheme##fread\:\/\/interestingnovel\/reader\?readType=0\&bookId=##https://androidapi4.yc.ifeng.com/api/books/?bookid=
*/

//⚠️正文解密By_尐哖：
function m(bArr) {
	i = 0;
	for (i2 = 0; i2 < 2; i2++) {
		i = parseInt(i) + parseInt(bArr[i2] < 0 ? (bArr[i2] + 256) : bArr[i2] << (i2 * 8));
  }
  return i;
}
function decode(bArr){
	length = bArr.length / 2;
  for (i = 0,str = ''; i < length; i++) {
  	i2 = i * 2;
  	b = bArr[i2];
   b2 = bArr[i2 + 1];
   if (b == -1 && b2 == -2) {str += ' ';} 
   else if (b == 13 && b2 == 0) {str += ' ';} 
   else {
     str += String.fromCharCode(((b2 << 8) & 65280) | (b & 255));
   }
  }
  return str;
}

source.exploreUrl:
@js:
sort=[];
burl=source.getKey();
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
function fl(a){
		url=burl+`/api/newBookRoom/list?clsID=${a}&pageNum=1&pageSize=10000`;
		return  JSON.parse(java.ajax(url)).data;
}
function ul(b){
	url = `/api/newClassify/list?classfyIDs=${b}&pageNum=1&pageSize=10000`;
	return url;
}		
//全部：1
		[["男生",fl(98).contentList],
		["女频",fl(122).contentList],
		["出版",fl(79).contentList]].map([tit1,list]=>{				
    	[["连载","2"],["完本","3"]].map([tit2,status]=>{	   			
				push(tit1+'-'+tit2, null, 1, 1);
				list.map(($,index)=>{
					title = $.title;
					id = $.scheme.match(/classfyIDs=(\d+,\d+),/)[1]
					label_id=id+','+status;
					url=ul(label_id);
					if(index+1 <= list.length - list.length%3){
						push(title, url, 1, 0.25);}
						else{ push(title, url, 0, 0.29);}
        });   
       });
  });

JSON.stringify(sort);

